			isTTY:     true,
			canPrompt: true,
			provider:  nil,
			wantTUI:   true,
			wantDump:  true,
			wantTotal: 2,
		},
		{
			name:      "tty without prompt skips synth even with provider",
			isTTY:     true,
			canPrompt: false,
			provider:  provider,
			wantTUI:   true,
			wantDump:  true,
			wantTotal: 2,
		},
