func commitWithMessage(t *testing.T, repoRoot, path, content, subject, body string) string {
	t.Helper()
	testutil.WriteFile(t, repoRoot, path, content)
	testutil.GitAdd(t, repoRoot, path)
	args := []string{"commit", "-m", subject}
	if body != "" {
