func findReviewBriefRow(t *testing.T, brief, needle string) string {
	t.Helper()
	for _, line := range strings.Split(brief, "\n") {
		if strings.Contains(line, needle) {
			return line
		}
	}
	t.Fatalf("brief missing row containing %q:\n%s", needle, brief)
	return ""
}

