+func reviewCheckpointContext(ctx context.Context, worktreeRoot string, scopeBaseRef string) string {
+	return renderReviewCheckpointContextForRepo(ctx, worktreeRoot, scopeBaseRef)
+}
+
+func renderReviewCheckpointContextForRepo(ctx context.Context, repoRoot string, scopeBaseRef string) (contextText string) {
+	defer func() {
+		if r := recover(); r != nil {
+			logging.Debug(ctx, "review checkpoint context: panic while rendering", slog.Any("panic", r))
+			contextText = ""
+		}
+	}()
+
+	if scopeBaseRef == "" {
+		return ""
+	}
+	commits, err := reviewContextGitLines(ctx, repoRoot, "rev-list", scopeBaseRef+"..HEAD")
+	if err != nil {
+		logging.Debug(ctx, "review checkpoint context: list commits",
+			slog.String("base_ref", scopeBaseRef),
+			slog.String("error", err.Error()))
+		return ""
+	}
+	if len(commits) == 0 {
+		return ""
+	}
+
+	repo, err := git.PlainOpen(repoRoot)
+	if err != nil {
+		logging.Debug(ctx, "review checkpoint context: open repository", slog.String("error", err.Error()))
+		return ""
+	}
+	v1Store := checkpoint.NewGitStore(repo)
+	v2URL, urlErr := remote.FetchURL(ctx)
+	if urlErr != nil {
+		logging.Debug(ctx, "review checkpoint context: no configured v2 fetch remote", slog.String("error", urlErr.Error()))
+		v2URL = ""
+	}
+	v2Store := checkpoint.NewV2GitStore(repo, v2URL)
+	preferV2 := settings.IsCheckpointsV2Enabled(ctx)
+
+	rows := make([]reviewCheckpointContextRow, 0, len(commits))
+	for _, commit := range commits {
+		row := reviewCheckpointContextRow{
+			commit:     shortReviewContextHash(commit),
+			checkpoint: "-",
+			files:      reviewContextChangedFileCount(ctx, repoRoot, commit),
+			agent:      "-",
+			subject:    truncateReviewContextSubject(reviewContextGitString(ctx, repoRoot, "show", "-s", "--format=%s", commit)),
+		}
+
+		message := reviewContextGitString(ctx, repoRoot, "show", "-s", "--format=%B", commit)
+		if checkpointID, ok := trailers.ParseCheckpoint(message); ok {
+			row.checkpoint = checkpointID.String()
+			reader, summary, resolveErr := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, preferV2)
+			if resolveErr != nil || summary == nil {
+				logging.Debug(ctx, "review checkpoint context: unresolved checkpoint",
+					slog.String("commit", commit),
+					slog.String("checkpoint_id", checkpointID.String()),
+					slog.Any("error", resolveErr))
+				row.checkpoint = checkpointID.String() + " (unresolved)"
+			} else {
+				row.files = len(summary.FilesTouched)
+				row.agent = latestNonReviewAgentForContext(ctx, reader, checkpointID, summary)
+			}
+		}
+
+		rows = append(rows, row)
+	}
+
+	return formatReviewCheckpointContext(rows)
+}
+
+func reviewContextGitLines(ctx context.Context, repoRoot string, args ...string) ([]string, error) {
+	full := append([]string{"-C", repoRoot}, args...)
+	output, err := exec.CommandContext(ctx, "git", full...).Output()
+	if err != nil {
+		return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
+	}
+	trimmed := strings.TrimSpace(string(output))
+	if trimmed == "" {
+		return nil, nil
+	}
+	lines := strings.Split(trimmed, "\n")
+	result := lines[:0]
+	for _, line := range lines {
+		if line = strings.TrimSpace(line); line != "" {
+			result = append(result, line)
+		}
+	}
+	return result, nil
+}
+
+func reviewContextGitString(ctx context.Context, repoRoot string, args ...string) string {
+	lines, err := reviewContextGitLines(ctx, repoRoot, args...)
+	if err != nil || len(lines) == 0 {
+		return ""
+	}
+	return strings.Join(lines, "\n")
+}
+
+func shortReviewContextHash(commit string) string {
+	const shortCommitLength = 12
+	if len(commit) <= shortCommitLength {
+		return commit
+	}
+	return commit[:shortCommitLength]
+}
+
+func truncateReviewContextSubject(subject string) string {
+	const maxSubjectLength = 64
+	subject = strings.TrimSpace(subject)
+	if len(subject) <= maxSubjectLength {
+		return subject
+	}
+	return strings.TrimSpace(subject[:maxSubjectLength-3]) + "..."
+}
+
+func reviewContextChangedFileCount(ctx context.Context, repoRoot string, commit string) int {
+	lines, err := reviewContextGitLines(ctx, repoRoot, "diff-tree", "--no-commit-id", "--name-only", "-r", "--root", commit)
+	if err != nil {
+		logging.Debug(ctx, "review checkpoint context: count changed files",
+			slog.String("commit", commit),
+			slog.String("error", err.Error()))
+		return 0
+	}
+	return len(lines)
+}
+
+func latestNonReviewAgentForContext(
+	ctx context.Context,
+	reader checkpoint.CommittedReader,
+	checkpointID checkpointid.CheckpointID,
+	summary *checkpoint.CheckpointSummary,
+) string {
+	for i := len(summary.Sessions) - 1; i >= 0; i-- {
+		metadata, err := readReviewContextSessionMetadata(ctx, reader, checkpointID, i)
+		if err != nil {
+			logging.Debug(ctx, "review checkpoint context: read session metadata",
+				slog.String("checkpoint_id", checkpointID.String()),
+				slog.Int("session_index", i),
+				slog.String("error", err.Error()))
+			continue
+		}
+		if metadata == nil || metadata.Kind.IsReview() || metadata.Agent == "" {
+			continue
+		}
+		ag, err := agent.GetByAgentType(metadata.Agent)
+		if err != nil {
+			return string(metadata.Agent)
+		}
+		return string(ag.Name())
+	}
+	return "-"
+}
+
+func readReviewContextSessionMetadata(
+	ctx context.Context,
+	reader checkpoint.CommittedReader,
+	checkpointID checkpointid.CheckpointID,
+	sessionIndex int,
+) (*checkpoint.CommittedMetadata, error) {
+	if metadataReader, ok := reader.(reviewContextSessionMetadataReader); ok {
+		metadata, err := metadataReader.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
+		if err != nil {
+			return nil, fmt.Errorf("read session metadata: %w", err)
+		}
+		return metadata, nil
+	}
+	content, err := reader.ReadSessionContent(ctx, checkpointID, sessionIndex)
+	if err != nil {
+		return nil, fmt.Errorf("read session content: %w", err)
+	}
+	if content == nil {
+		return nil, errors.New("session content is nil")
+	}
+	return &content.Metadata, nil
+}
+
+func formatReviewCheckpointContext(rows []reviewCheckpointContextRow) string {
+	const (
+		commitHeader     = "commit"
+		checkpointHeader = "checkpoint"
+		filesHeader      = "files"
+		agentHeader      = "agent"
+		subjectHeader    = "subject"
+	)
+
+	commitWidth := len(commitHeader)
+	checkpointWidth := len(checkpointHeader)
+	filesWidth := len(filesHeader)
+	agentWidth := len(agentHeader)
+	for _, row := range rows {
+		commitWidth = max(commitWidth, len(row.commit))
+		checkpointWidth = max(checkpointWidth, len(row.checkpoint))
+		filesWidth = max(filesWidth, len(strconv.Itoa(row.files)))
+		agentWidth = max(agentWidth, len(row.agent))
+	}
+
+	var sb strings.Builder
+	sb.WriteString("Commits in scope (newest first):\n\n")
+	fmt.Fprintf(&sb, "  %-*s  %-*s  %*s  %-*s  %s\n",
+		commitWidth, commitHeader,
+		checkpointWidth, checkpointHeader,
+		filesWidth, filesHeader,
+		agentWidth, agentHeader,
+		subjectHeader)
+	for _, row := range rows {
+		fmt.Fprintf(&sb, "  %-*s  %-*s  %*d  %-*s  %s\n",
+			commitWidth, row.commit,
+			checkpointWidth, row.checkpoint,
+			filesWidth, row.files,
+			agentWidth, row.agent,
+			row.subject)
+	}
+	sb.WriteString("\n")
+	sb.WriteString("Use checkpoint IDs and commit hashes to inspect details:\n")
+	sb.WriteString("  - `entire explain <id>` (for example `entire explain ")
+	sb.WriteString(firstReviewCheckpointExample(rows))
+	sb.WriteString("`)\n")
+	sb.WriteString("  - `entire explain <id> --raw-transcript` (for example `entire explain ")
+	sb.WriteString(firstReviewCheckpointExample(rows))
+	sb.WriteString(" --raw-transcript`) for the raw checkpoint transcript\n")
+	sb.WriteString("  - `git show <commit>` for the commit diff\n")
+	return sb.String()
+}
+
+func firstReviewCheckpointExample(rows []reviewCheckpointContextRow) string {
+	for _, row := range rows {
+		if row.checkpoint != "-" && !strings.Contains(row.checkpoint, " ") {
+			return row.checkpoint
+		}
+	}
+	return "<id>"
+}
