func newReviewContextRepo(t *testing.T) string {
	t.Helper()
	tmp := t.TempDir()
	testutil.InitRepo(t, tmp)
	testutil.WriteFile(t, tmp, "base.txt", "base\n")
	testutil.GitAdd(t, tmp, "base.txt")
	testutil.GitCommit(t, tmp, "base")
	testutil.GitCheckoutNewBranch(t, tmp, "feat/review")
	return tmp
}

func commitReviewContextChange(t *testing.T, repoRoot, path, content, subject, body string) string {
	t.Helper()
	testutil.WriteFile(t, repoRoot, path, content)
	testutil.GitAdd(t, repoRoot, path)
	message := subject
	if body != "" {
		message += "\n\n" + body
	}
	testutil.GitCommit(t, repoRoot, message)
	return testutil.GetHeadHash(t, repoRoot)
}

func writeReviewContextCheckpoint(
	t *testing.T,
	repoRoot string,
	checkpointID string,
	filesTouched []string,
	agentType types.AgentType,
	kind session.Kind,
) {
	t.Helper()
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}
	store := checkpoint.NewGitStore(repo)
	cpID := checkpointid.MustCheckpointID(checkpointID)
	err = store.WriteCommitted(context.Background(), checkpoint.WriteCommittedOptions{
		CheckpointID:     cpID,
		SessionID:        checkpointID + "-" + strings.ReplaceAll(string(kind), "_", "-"),
		Strategy:         "manual-commit",
		Branch:           "feat/review",
		Transcript:       redact.AlreadyRedacted([]byte(`{"event":"test"}` + "\n")),
		Prompts:          []string{"test prompt"},
		FilesTouched:     filesTouched,
		CheckpointsCount: 1,
		Agent:            agentType,
		Kind:             string(kind),
		HasReview:        kind.IsReview(),
	})
	if err != nil {
		t.Fatalf("write checkpoint: %v", err)
	}
}

func installReviewContextClaudeHooks(t *testing.T, ctx context.Context) {
