	readContentCalls int
}

func (r *metadataOnlyReviewContextReader) ReadCommitted(
	context.Context,
	checkpointid.CheckpointID,
) (*checkpoint.CheckpointSummary, error) {
	return &checkpoint.CheckpointSummary{Sessions: make([]checkpoint.SessionFilePaths, len(r.metadata))}, nil
}

func (r *metadataOnlyReviewContextReader) ReadSessionContent(
	context.Context,
	checkpointid.CheckpointID,
	int,
) (*checkpoint.SessionContent, error) {
	r.readContentCalls++
	return nil, errors.New("ReadSessionContent should not be called by latestNonReviewAgentForContext")
}

func (r *metadataOnlyReviewContextReader) ReadSessionMetadata(
	_ context.Context,
	_ checkpointid.CheckpointID,
	sessionIndex int,
) (*checkpoint.CommittedMetadata, error) {
	if sessionIndex < 0 || sessionIndex >= len(r.metadata) {
		return nil, errors.New("session not found")
	}
	return &r.metadata[sessionIndex], nil
}

